#include <stdint.h>
#include "regs.h"

#if !defined(__SOFT_FP__) && defined(__ARM_FP)
  #warning "FPU is not initialized, but the project is compiling for an FPU. Please initialize the FPU before use."
#endif

volatile uint32_t ms_counter = 0;
volatile uint32_t last_ms_counter = 0;

void SysTick_Handler(void){
		ms_counter ++;
}

void EXTI0_IRQHandler(void){
	EXTI_PR |= (0x1);
	if(ms_counter - last_ms_counter > 20){
		GPIOC_ODR ^= (1 << 13);
		last_ms_counter = ms_counter;
	}
}

int main(void)
{
	RCC_APB2ENR |= (1 << 4);
	RCC_APB2ENR |= (1 << 2);
	RCC_APB2ENR |= (1 << 0);//分别使能
	GPIOC_CRH &= ~(0xF << 20);//清零
	GPIOC_CRH |= (0X2 << 20);//模式，0010
	GPIOA_CRL &= ~(0xF);//清零
	GPIOA_CRL |= (0x8);//模式：1000
	GPIOA_ODR |= (0x1);//上拉初始化
	GPIOC_ODR |= (1 << 13);//初始高电平，灭灯
	AFIO_EXTICR1 &= ~(0xF);//exit线接pa0
	EXTI_FTSR |= (0x1);//打开下降沿触发，因为是接地翻转
	EXTI_IMR |= (0x1 << 0);//打开中断屏蔽
	NVIC_ISER0 |= (0x1 << 6);
	SYST_RVR = 999;//跑1000次，1ms中断
	SYST_CSR |= (1<<0) | (1<<1);

    /* Loop forever */
	for(;;);
}
